def overlaps(self, other: "Session") -> bool:
    """True when the two sessions' time intervals overlap on the same day.
    Overlap is strict: touching end/start does NOT count as overlap.
    """
    # Sessions must be on the same day and have intersecting intervals.
    return (
        self.day == other.day
        and self.start_minutes < other.end_minutes
        and other.start_minutes < self.end_minutes
    )

